INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(95937, 'ruRU', '', 'Лей-ткач Митроган, прямо за пределами этого зала, знает этот чертёж.', 24330),
(95938, 'ruRU', '', 'Тебе стоит поговорить с лей-ткачом Джорджаной, в южном Сурамаре, в Портовом районе. Я отмечу её местоположение на твоей карте.', 24330),
(95939, 'ruRU', '', 'Лей-ткач Эрени. Сейчас она исследует друидские чертежи в Вал''шаре. Я отмечу её местоположение на твоей карте.', 24330),
(95940, 'ruRU', '', 'Поговори с лей-ткачом Яфистеей. Она бродит по дорогам Высокогорья. Я отмечу её местоположение на твоей карте.', 24330),
(95941, 'ruRU', '', 'Полагаю, лей-ткач Атистро знает этот чертёж. Ты найдёшь его прямо к западу отсюда, откуда он наблюдает за Приютом Осквернённых Душ. Я отмечу его местоположение на твоей карте.', 24330),
(95942, 'ruRU', '', 'Лей-ткач Теллуми, которая сейчас путешествует по Штормхейму, хранит этот чертёж для нашей гильдии. Я отмечу её местоположение на твоей карте.', 24330),
(95943, 'ruRU', '', 'Наплечная броня — вотчина лей-ткача Факсондуса. Он предпочитает проводить время у открытых лей-линий Азсуны. Я отмечу его местоположение на твоей карте.', 24330),
(95944, 'ruRU', '', 'Тебе повезло. Я могу сам обучить тебя этим чертежам.$b$bНо это будет стоить. Наши клиенты требовательны, а наша мастерская потребляет огромное количество сырья.', 24330),
(95946, 'ruRU', '', 'Когда-нибудь, надеюсь, я увижу этот ваш "Азерот". Должно быть, это удивительный мир.', 24330),
(95954, 'ruRU', '', 'Все целы?', 24330),
(95956, 'ruRU', '', 'Держитесь! Удержите эту линию, или Менетил падёт!', 24330),
(95957, 'ruRU', '', 'Фронт прорван! Держитесь, я уверен, подкрепление уже в пути!', 24330),
(95958, 'ruRU', '', 'Оплакивать их будем позже, нужно двигаться, пока не прибыли новые демоны.', 24330),
(95961, 'ruRU', '', 'Я никогда не видел, чтобы демоны расширялись так быстро.', 24330),
(95974, 'ruRU', '', 'О нет...', 24330),
(95979, 'ruRU', '', 'Приветствую, путник. Наша поляна знавала более мирные времена, но друиды Когтя предлагают всю защиту, какую можем дать.', 24330),
(95981, 'ruRU', '', 'Улицы Даларана совершенно безопасны, уверяю тебя. Едва ли удивительно, что кто-то может напасть на одну из этих... тварей.', 24330),
(96049, 'ruRU', '', 'Вариан!', 24330),
(96051, 'ruRU', '', 'Вот, попробуй этот чертёж. И используй мои материалы! Найдёшь их разбросанными по мастерской.', 24330),
(96052, 'ruRU', '', 'Теперь, когда ты собрал нужные материалы, закончи чертёж на моём рабочем столе.', 24330),
(96053, 'ruRU', '', 'Что это? Что происходит с твоей нитью? Почему мантия ДЫМИТСЯ?', 24330),
(96054, 'ruRU', '', 'Какая катастрофа. Смотри, нить просто выпадает прямо из ткани. Никогда раньше такого не видел.', 24330),
(96055, 'ruRU', '', 'Приготовься, герой. Тварь спускается!', 24330),
(96056, 'ruRU', '', 'У нас получилось! Карликовые совы этой рощи теперь в безопасности благодаря тебе.', 24330),
(96083, 'ruRU', '', 'Бесполезно, боеприпасы загорелись! Быстро, вверх по лестнице!', 24330),
(96085, 'ruRU', '', 'На моём мире появились охотники на демонов, командир гибели. Это недопустимо.', 24330),
(96089, 'ruRU', '', 'Мои пауки попируют твоим костным мозгом.', 24330),
(96109, 'ruRU', '', 'Не дай им войти в вулкан. Ключ к мирам Легиона не должен попасть к ним в руки, Белиаш.', 24330),
(96112, 'ruRU', '', 'Этот день станет для тебя последним!', 24330),
(96135, 'ruRU', '', 'Ну-ну. Они просто не могут не быть такими бойкими.', 24330),
(96146, 'ruRU', '', 'Разберись с этими насекомыми, Белиаш.', 24330),
(96166, 'ruRU', '', 'Взял их на прицел!', 24330),
(96167, 'ruRU', '', 'Вижу их. Отличная работа с оглушающими гранатами, $Gпарень:девчонка;!', 24330),
(96168, 'ruRU', '', 'Да ни за что я не промажу этим выстрелом!', 24330),
(96169, 'ruRU', '', 'Взял этого, ясно как день.', 24330),
(96170, 'ruRU', '', 'Бабах! Прямо в физиономию!', 24330),
(96171, 'ruRU', '', 'Кто-то заказывал яблочко?', 24330),
(96172, 'ruRU', '', 'Выстрел в голову. Проще некуда.', 24330),
(96173, 'ruRU', '', 'Как стрелять рыбу в чёртовой бочке.', 24330),
(96181, 'ruRU', '', 'Ну-ка, подойди ближе, дай мне как следует тебя рассмотреть.$B$BАх! $c, да ещё и в этих краях? Батюшки мои!', 24330);
